<span class="line"><span style="color:#839496;">    cache.store_word(A </span><span style="color:#859900;">+</span><span style="color:#93A1A1;font-weight:bold;"> 0x</span><span style="color:#D33682;">24</span><span style="color:#839496;">, </span><span style="color:#D33682;">12</span><span style="color:#839496;">)</span></span>
