<span class="line"><span style="color:#268BD2;">    print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;A 入队后，缓冲内&quot;</span><span style="color:#839496;">, first_two_words(wb.writeback[</span><span style="color:#D33682;">1</span><span style="color:#839496;">]))</span></span>
